(async () => {
  try {
    const res = await fetch("https://sdp-prem-prod.premier-league-prod.pulselive.com/api/v5/competitions/8/seasons/2025/standings", {
      method: "GET"
    });
    const info = { status: res.status, ok: res.ok };
    let bodyText = null;
    try {
      bodyText = await res.text();
    } catch (e) {
      info.bodyReadError = String(e);
    }
    info.bodySnippet = bodyText ? bodyText.slice(0, 2048) : null;
    return { type: "success", result: info };
  } catch (e) {
    return { type: "error", message: String(e), name: e.name || null }; 
  }
})()
